// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.bulk;

import static org.assertj.core.api.Assertions.assertThat;

import java.lang.reflect.Method;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class CanonicalTermCodecTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void canonicalizesRdf4jEqualityAndRoundTripsNestedTripleTerms() throws Exception {
		Class<?> codec = Class.forName("org.eclipse.rdf4j.sail.lmdb.bulk.CanonicalTermCodec");
		Method encode = codec.getDeclaredMethod("encode", Value.class);
		Method decode = codec.getDeclaredMethod("decode", byte[].class);
		Method routeHash = codec.getDeclaredMethod("routeHash64", byte[].class);
		encode.setAccessible(true);
		decode.setAccessible(true);
		routeHash.setAccessible(true);

		byte[] lowerLanguage = (byte[]) encode.invoke(null, VF.createLiteral("label", "en"));
		byte[] upperLanguage = (byte[]) encode.invoke(null, VF.createLiteral("label", "EN"));
		assertThat(upperLanguage).isEqualTo(lowerLanguage);
		assertThat((long) routeHash.invoke(null, lowerLanguage))
				.isEqualTo((long) routeHash.invoke(null, upperLanguage));

		IRI predicate = VF.createIRI("urn:predicate");
		Value nested = VF.createTripleTerm(
				VF.createIRI("urn:outer-subject"), predicate,
				VF.createTripleTerm(VF.createIRI("urn:inner-subject"), predicate, VF.createLiteral("inner", "en")));
		byte[] nestedBytes = (byte[]) encode.invoke(null, nested);
		assertThat(decode.invoke(null, nestedBytes)).isEqualTo(nested);
		assertThat(nestedBytes).isNotEqualTo((byte[]) encode.invoke(null, VF.createIRI(nested.stringValue())));
	}
}
